# R(route_id, a, b, kind, watches, terrain, **kw)
def R(rid, a, b, kind, watches, terrain, **kw):
    d = dict(route=rid, a=a, b=b, route_kind=kind, travel_watches=watches, terrain=terrain, known=True, danger=None, hazards=[], vehicle_ok=[], current=None)
    d.update(kw)
    return d

